import { recommendations, verifiedHours } from "./domain.js";
export const escapeHTML = (v = "") => String(v).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
const x = escapeHTML;
export function commonNav(role, route) {
  return `<nav class="community-nav" aria-label="Primary"><a class="community-brand" href="#/community"><span aria-hidden="true">◆</span> CivicShift<span class="demo-badge">DEMO</span></a><div class="primary-links"><a href="#/community" ${route === "community" ? 'aria-current="page"' : ""}>Community</a><a href="#/explore" ${route === "explore" ? 'aria-current="page"' : ""}>Opportunities</a><a href="#/dashboard" ${route === "dashboard" ? 'aria-current="page"' : ""}>My dashboard</a></div><button class="button button-primary" type="button" data-assistant-open>✦ <span>Demo assistant</span></button></nav>`;
}
export function visibleStories(state, ui, student) {
  const saved = state.savedStories[student.id] || [];
  const matches = recommendations(state,student);
  return state.stories.filter(story => story.status === "published")
    .filter(story => ui.feedTab !== "saved" || saved.includes(story.id))
    .filter(story => !ui.feedCause || ui.feedCause === "all" || story.cause === ui.feedCause)
    .filter(story => !ui.feedSearch || `${story.title} ${story.summary} ${story.locality} ${story.cause} ${story.publisher}`.toLowerCase().includes(ui.feedSearch.toLowerCase()))
    .sort((a,b) => {
      const weight = story => Math.max(0,...matches.filter(i => story.eventIds.includes(i.event.id) && !i.blocked).map(i => i.score));
      return (ui.feedTab === "latest" || ui.feedTab === "saved" ? 0 : weight(b)-weight(a)) || b.date.localeCompare(a.date);
    });
}
export function feedView(state,ui,student) {
  const stories = visibleStories(state,ui,student), saved = state.savedStories[student.id] || [];
  const matches = recommendations(state,student);
  const hours = verifiedHours(state,student.id), goal = student.requirementGoal;
  const commitments = state.signups.filter(r => r.studentId === student.id && ["approved","pending","offered"].includes(r.status)).map(r => ({r,e:state.events.find(e => e.id===r.eventId)})).filter(i=>i.e?.status==="active" && i.e.date>=state.clock.slice(0,10)).sort((a,b)=>a.e.date.localeCompare(b.e.date));
  const causes = [...new Set(state.stories.filter(s=>s.status==="published").map(s=>s.cause))];
  return `<section class="feed-intro"><div><span class="eyebrow">YOUR COMMUNITY. YOUR NEXT MOVE.</span><h1>Good things start<br>with <em>showing up.</em></h1><p>Find a cause that moves you. Turn a little of your time into something that matters, close to home.</p></div><div class="intro-note"><span aria-hidden="true">↗</span><strong>Small steps.<br>Shared impact.</strong><p>Cupertino & the Bay Area</p></div></section>
    <div class="fiction-note"><span class="live-dot" aria-hidden="true"></span> Fictional community stories & organizations · Browser-local demo · Clock: ${x(state.clock.replace("T"," "))}</div>
    <div class="feed-layout"><section aria-label="Community needs"><div class="feed-toolbar"><div class="feed-tabs" role="group" aria-label="Feed view">${[["for-you","For You"],["latest","Latest"],["saved","Saved"]].map(([id,label])=>`<button type="button" data-feed-tab="${id}" aria-pressed="${(ui.feedTab||"for-you")===id}">${label}${id==="saved"?` <span>${saved.filter(id=>state.stories.some(s=>s.id===id&&s.status==="published")).length}</span>`:""}</button>`).join("")}</div><span class="feed-count">${stories.length} stories</span></div>
    <form class="feed-search" data-form="feed-filter"><div class="field"><label for="feed-search">Search your community</label><input id="feed-search" name="search" type="search" value="${x(ui.feedSearch||"")}" placeholder="Try reading, Cupertino, or food…"></div><div class="field"><label for="feed-cause">Cause</label><select id="feed-cause" name="cause"><option value="all">All causes</option>${causes.map(c=>`<option ${ui.feedCause===c?"selected":""}>${x(c)}</option>`).join("")}</select></div><button class="button button-light" type="submit">Search</button></form>
    <div class="story-list">${stories.length?stories.map(story=>{
      const linked = story.eventIds.map(id=>state.events.find(e=>e.id===id)).filter(e=>e?.status==="active" && e.date>=state.clock.slice(0,10));
      const best = matches.find(i=>story.eventIds.includes(i.event.id) && !i.blocked);
      return `<article class="story-card"><div class="story-art art-${x(story.art)}" aria-hidden="true"><span class="art-caption">${x(story.label)}</span><div class="art-orbit"></div><div class="art-symbol">${({creek:"↟",books:"Aa",food:"✳",tech:"↗",paws:"✿",wellness:"＋"})[story.art]||"✳"}</div><span class="art-locality">${x(story.locality)} ↗</span></div><div class="story-body"><div class="story-meta"><span class="publisher-avatar">${x(story.publisher.slice(0,1))}</span><div><strong>${x(story.publisher)}</strong><span><time datetime="${story.date}">${new Date(story.date+"T12:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric"})}</time> · ${x(story.locality)} · Fictional story</span></div><button class="story-save" type="button" data-save-story="${story.id}" aria-pressed="${saved.includes(story.id)}" aria-label="${saved.includes(story.id)?"Unsave":"Save"} story: ${x(story.title)}">${saved.includes(story.id)?"♥":"♡"}</button></div><span class="story-cause">${x(story.cause)}</span><h2>${x(story.title)}</h2><p>${x(story.summary)}</p><details class="why-match"><summary>Why this is in your feed</summary><p>${best?.reasons.length?best.reasons.map(x).join(". ")+".":"Explore this community need to discover a new cause."} Recommendations use your saved profile and weekly availability. Review each shift’s requirements.</p></details><div class="story-opportunities"><span>TURN INTEREST INTO ACTION</span>${linked.length?linked.map(e=>`<a href="#/event/${e.id}"><div><strong>${x(e.title)}</strong><small>${x(e.date)} · ${e.shifts.length} ${e.shifts.length===1?"shift":"shifts"} · ${x(e.location)}</small></div><span aria-hidden="true">↗</span></a>`).join(""):"<p>No upcoming linked shifts. Explore other opportunities.</p>"}</div></div></article>`;
    }).join(""):"<div class='card empty'><h2>No stories here yet.</h2><p>Try another search or save a story to revisit it.</p></div>"}</div></section>
    <aside class="feed-aside" aria-label="Your service snapshot"><article class="service-card"><div class="card-head"><h2>Your next chapter</h2><span aria-hidden="true">↗</span></div><p>Demo student · ${x(student.name)}</p><div class="goal-number"><strong>${hours.toFixed(2)}</strong><span>/ ${goal} hours</span></div><div class="progress" role="progressbar" aria-label="Verified hours toward your goal" aria-valuenow="${Math.min(hours,goal)}" aria-valuemin="0" aria-valuemax="${goal}"><span style="width:${Math.min(100,hours/goal*100)}%"></span></div><p>${Math.max(0,goal-hours).toFixed(2)} hours to your goal. Every verified hour counts.</p><a href="#/hours">View time cards →</a></article><article class="card commitment-card"><h2>On your calendar</h2>${commitments.length?commitments.slice(0,3).map(({r,e})=>`<a class="commitment" href="#/event/${e.id}"><time>${x(e.date.slice(5))}</time><div><strong>${x(e.title)}</strong><span>${x(e.shifts.find(s=>s.id===r.shiftId)?.name)} · ${x(r.status)}</span></div></a>`).join(""):"<p>Your next commitment could start here.</p>"}<a href="#/dashboard">Open your dashboard →</a></article><article class="assistant-teaser"><span aria-hidden="true">✦</span><h2>A little help getting started.</h2><p>Find a shift that fits, check a conflict, or see your remaining hours.</p><button class="button button-light" type="button" data-assistant-open>Ask the demo assistant ↗</button><small>Scripted assistance. You confirm every registration change.</small></article><a class="feed-about" href="#/about">About this student project ↗</a></aside></div>`;
}
export function storiesView(state) {
  return `<div class="page-head"><div><span class="eyebrow">Community publishing</span><h1>Make a need visible.</h1><p>Publish or hide fictional demo stories. Hidden stories disappear from every feed, including Saved.</p></div></div><section class="grid grid-2">${state.stories.map(s=>`<article class="card"><span class="tag">${x(s.status)}</span><h2>${x(s.title)}</h2><p>${x(s.publisher)} · ${x(s.locality)}</p><button class="button button-primary" data-story-status="${s.id}" data-status="${s.status==="published"?"hidden":"published"}">${s.status==="published"?"Hide story":"Publish story"}</button></article>`).join("")}</section>`;
}
